-- ── Accessors ───────────────────────────────────────────────────────────
-- Emitted from the importer template, not hand-written: this file is
-- overwritten wholesale on every pipeline run, so an accessor added by
-- hand here would vanish on the next one (CLAUDE.md).

function CodexData:GetRenownFaction(factionID)
    factionID = tonumber(factionID)
    return factionID and Renown[factionID] or nil
end

-- Display-shaped rows for NormalizedData's reputation merge, which reads
-- Providers[tag]:GetReputationEntries(). Without this the provider has no
-- consumer and the import is dead weight -- which is exactly what the
-- previous all-zero version of this file was.
function CodexData:GetReputationEntries()
    if self._renownEntries then
        return self._renownEntries
    end
    local entries = {}
    for factionID, rec in pairs(Renown) do
        if type(rec) == "table" and type(rec.rewards) == "table" then
            local itemIds, standings, seenStanding = {}, {}, {}
            for _, reward in ipairs(rec.rewards) do
                if reward.itemId and reward.itemId > 0 then
                    itemIds[#itemIds + 1] = reward.itemId
                end
                local standing = reward.requiredStanding
                if standing and not seenStanding[standing] then
                    seenStanding[standing] = true
                    standings[#standings + 1] = standing
                end
            end
            local vendorNames = {}
            for _, vendor in ipairs(rec.vendors or {}) do
                if vendor.name then
                    vendorNames[#vendorNames + 1] = vendor.name
                end
            end
            entries[#entries + 1] = {
                key = tostring(factionID),
                title = rec.label or tostring(factionID),
                subtitle = string.format("%s • %d rewards", rec.expansionKey or "", #itemIds),
                detail = string.format("HousingReps renown donor. Vendors: %s • Standings: %s",
                    table.concat(vendorNames, ", "), table.concat(standings, ", ")),
                entryType = "reputation",
                -- itemIds, not decorIds: this donor carries item IDs and the
                -- decor mapping is resolved live via Villa:ItemIDToDecorID.
                itemIds = itemIds,
                decorIds = {},
                owned = 0,
                total = #itemIds,
            }
        end
    end
    self._renownEntries = entries
    return entries
end

if Villa.RegisterModule and type(Villa.RegisterModule) == "function" then
    Villa:RegisterModule("CodexData.Renown", Renown)
end
